<div class="card p-4 p-md-5"><div class="d-flex justify-content-between align-items-start flex-wrap gap-2"><div><span class="eyebrow">PEDIDO CONFIRMADO</span><h2 class="section">Pedido #<?=$o['id']?></h2><small class="text-muted">Referencia <?=e($o['payment_reference'])?></small></div><a class="btn grad me-2" href="/?r=invoice&id=<?=$o['id']?>">Descargar factura PDF</a><span class="orderstatus big"><?=e(str_replace('_',' ',$o['status']))?></span></div><div class="order-timeline"><?php $steps=['PEDIDO','PREPARACION','LISTO','EN_CAMINO','ENTREGADO'];$pos=array_search($o['status'],$steps,true);foreach($steps as $i=>$s):?><span class="<?=$pos!==false&&$i<=$pos?'done':''?>"><?=str_replace('_',' ',$s)?></span><?php endforeach;?></div><div class="row g-4"><div class="col-lg-7"><h5>Productos</h5><?php foreach($o['items'] as $i):?><div class="order-item"><img src="/<?=e($i['image'])?>"><div><b><?=e($i['name'])?></b><small>SKU <?=e($i['sku'])?> · Cantidad <?=(int)$i['quantity']?></small></div><b>Q<?=number_format($i['subtotal'],2)?></b></div><?php endforeach;?><div class="card-lite mt-4"><h5>Seguimiento</h5><?php foreach($o['history'] as $h):?><div class="history-row"><span class="history-dot"></span><div><b><?=e(str_replace('_',' ',$h['status']))?></b><small><?=e($h['created_at'])?><?=!empty($h['changed_name'])?' · '.e($h['changed_name']):''?></small></div></div><?php endforeach;?></div></div><div class="col-lg-5"><div class="deliverybox"><b>Cliente</b><br><?=e($o['fullname'])?><br><?=e($o['email'])?><hr><b>Entrega</b><br><?=e($o['shipping_method']==='RETIRO'?'Retiro en punto de entrega':'Entrega a domicilio')?><br><?=e($o['address'])?><hr><b>Pago</b><br><?=e($o['card_brand']?:'Tarjeta')?> terminada en •••• <?=e($o['card_last4'])?><br><span class="text-success fw-bold"><?=e($o['payment_status'])?></span><hr><div class="sumrow"><span>Subtotal</span><b>Q<?=number_format($o['subtotal'],2)?></b></div><div class="sumrow"><span>Envío</span><b>Q<?=number_format($o['shipping_cost'],2)?></b></div><div class="sumrow total"><span>Total</span><b>Q<?=number_format($o['total'],2)?></b></div></div></div></div></div>
